use super::*;

// Go: TestXMoveRenderParse.
#[test]
fn xmove_render_parse() {
    let xm = XMove {
        source_stack: "stacks/a".into(),
        pairs: vec![
            Move::new("aws_s3_bucket.x", "aws_s3_bucket.x"),
            Move::new(r#"aws_iam_member.m["a"]"#, r#"aws_iam_member.m["a"]"#),
        ],
    };
    let content = render_xmove("PR-5", &xm);
    let want = [
        "# Generated by `tfstackplan state move --via mv` — do not edit by hand. Executed by `tfstackplan state apply`.",
        "# tfstackplan:key=PR-5",
        "",
        "xmove {",
        "  source_stack = \"stacks/a\"",
        "  moves = {",
        "    \"aws_s3_bucket.x\" = \"aws_s3_bucket.x\"",
        "    \"aws_iam_member.m[\\\"a\\\"]\" = \"aws_iam_member.m[\\\"a\\\"]\"",
        "  }",
        "}",
        "",
    ]
    .join("\n");
    assert_eq!(content, want);
    let (key, got) = parse_xmove(&content).unwrap();
    assert_eq!(key, "PR-5");
    assert_eq!(got.source_stack, "stacks/a");
    // Pairs come back sorted by from.
    assert_eq!(
        got.pairs,
        vec![
            Move::new(r#"aws_iam_member.m["a"]"#, r#"aws_iam_member.m["a"]"#),
            Move::new("aws_s3_bucket.x", "aws_s3_bucket.x"),
        ]
    );
}

// Go: TestParseXMoveMissingKeyHeaderReturnsEmpty.
#[test]
fn parse_xmove_missing_key_header_returns_empty() {
    let content = "xmove {\n  source_stack = \"stacks/a\"\n  moves = {\n    \"aws_s3_bucket.x\" = \"aws_s3_bucket.x\"\n  }\n}\n";
    let (key, xm) = parse_xmove(content).unwrap();
    assert_eq!(key, "");
    assert_eq!(xm.source_stack, "stacks/a");
}

#[test]
fn parse_xmove_errors() {
    assert!(
        parse_xmove("# tfstackplan:key=PR-1\nxmove { not valid hcl\n")
            .unwrap_err()
            .starts_with("parse xmove: ")
    );
    assert_eq!(
        parse_xmove("# nothing\n").unwrap_err(),
        "xmove manifest has no xmove block"
    );
    assert!(
        parse_xmove("xmove {\n  moves = {}\n}\n")
            .unwrap_err()
            .starts_with("decode xmove: Missing required argument")
    );
    assert!(
        parse_xmove("other {}\n")
            .unwrap_err()
            .starts_with("decode xmove: ")
    );
}

#[test]
fn xmove_file_names() {
    assert_eq!(xmove_file_name("PR-5"), "_tfsp_xmove.PR-5.hcl");
    assert_eq!(xmove_key_from_file("_tfsp_xmove.PR-5.hcl"), Some("PR-5"));
    assert_eq!(xmove_key_from_file("_tfsp_move.PR-5.tf"), None);
}
